<script>
// Track menu states
let isOrganizationMenuOpen = false;
let isEmployeesMenuOpen = false;
let isAttendanceMenuOpen = false;
let isLeaveMenuOpen = false;
let isSubmissionsMenuOpen = false;
let isSystemSettingsMenuOpen = false;
let isPayrollMenuOpen = false;
let isOthersMenuOpen = false;


function toggleOrganizationMenu(event) {
    event.preventDefault();
    
    const submenu = document.getElementById('organization-submenu');
    const arrow = document.getElementById('organization-arrow');
    
    if (isOrganizationMenuOpen) {
        // Close animation
        submenu.style.maxHeight = submenu.scrollHeight + 'px';
        submenu.style.opacity = '1';
        
        // Force reflow
        submenu.offsetHeight;
        
        // Now animate to closed state
        submenu.style.maxHeight = '0px';
        submenu.style.opacity = '0';
        arrow.style.transform = 'rotate(0deg)';
        isOrganizationMenuOpen = false;
    } else {
        // Close employees menu if open
        if (isEmployeesMenuOpen) {
            toggleEmployeesMenu(event);
        }
        
